30: import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
31: 
32: import {
33:   type Sekolah,
34:   deliveryList,
35:   getSPPGBySekolah,
36:   getVendorsBySekolah,
37:   sekolahList,
38: } from "@/lib/mbgdummydata";
39: import { SchoolDetailPanel } from "@/components/ui/SchoolDetailPanel";
40: import VendorRanking from "@/components/ui/vendorranking";
41: import VendorPerformanceDashboard from "@/components/ui/VendorPerformanceDashboard";
42: import { KpiCard } from "@/components/ui/kpi-card";
43: import { cn } from "@/lib/utils";
44: 
45: const MapLibreMap = dynamic(() => import("@/components/ui/MapLibreMap"), { ssr: false });
46: 
47: const CATEGORIES = [
48:   { id: "overview", label: "Overview & Distribusi" },
49:   { id: "validasi", label: "Validasi Logistik" },
50:   { id: "mitra", label: "Mitra Operasional" },
51:   { id: "bantuan", label: "Bantuan & Tiket" },
52: ];
53: 
54: export default function SekolahAdminPage() {
55:   const [viewMode, setViewMode] = useState<"school" | "aggregate">("school");
56:   const [activeMitraTab, setActiveMitraTab] = useState<"performa" | "ranking">("performa");
57:   const [activeCategory, setActiveCategory] = useState<string>("overview");
58:   const [selectedSchool, setSelectedSchool] = useState<Sekolah | null>(null);
59:   const [selectedEntityId, setSelectedEntityId] = useState<number>(1);
60:   const [scanOpen, setScanOpen] = useState(false);
61:   const [lastScan, setLastScan] = useState<string | null>(null);
62: 
63:   // Scrollspy via IntersectionObserver
64:   useEffect(() => {
65:     const observerOptions = {
66:       root: null,
67:       rootMargin: "-20% 0px -55% 0px",
68:       threshold: 0,
69:     };
70: 
71:     const handleIntersect: IntersectionObserverCallback = (entries) => {
72:       entries.forEach((entry) => {
73:         if (entry.isIntersecting) {
74:           setActiveCategory(entry.target.id);
75:         }
76:       });
77:     };
78: 
79:     const observer = new IntersectionObserver(handleIntersect, observerOptions);
80: 
81:     CATEGORIES.forEach((cat) => {
82:       const el = document.getElementById(cat.id);
83:       if (el) observer.observe(el);
84:     });
85: 
86:     return () => observer.disconnect();
87:   }, []);
88: 
89:   const scrollToCategory = (id: string) => {
90:     setActiveCategory(id);
91:     const element = document.getElementById(id);
92:     if (element) {
93:       const yOffset = -90; // offset for sticky top navbar
94:       const y = element.getBoundingClientRect().top + window.pageYOffset + yOffset;
95:       window.scrollTo({ top: y, behavior: "smooth" });
96:     }
97:   };
98: 
99:   const loggedInSchool = useMemo(() => sekolahList.find((s) => s.id === 1) ?? null, []);
100:   const availableVendors = useMemo(
101:     () => (loggedInSchool ? getVendorsBySekolah(loggedInSchool.id) : []),
102:     [loggedInSchool]
103:   );
104:   const availableSPPG = useMemo(
105:     () => (loggedInSchool ? getSPPGBySekolah(loggedInSchool.id) : null),
106:     [loggedInSchool]
107:   );
108: 
109:   const primaryRelation = useMemo(
110:     () => availableVendors.find((v) => v.is_primary) ?? availableVendors[0] ?? null,
111:     [availableVendors]
112:   );
113: 
114:   const latestDelivery = useMemo(() => {
115:     if (!primaryRelation) return null;
116:     return (
117:       deliveryList
118:         .filter((d) => d.vendor_sekolah_id === primaryRelation.id)
119:         .sort((a, b) => b.id - a.id)[0] ?? null
120:     );
121:   }, [primaryRelation]);
122: 
123:   const identityPanels = useMemo(() => {
124:     const statusLabel =
125:       latestDelivery?.status === "on_transit"
126:         ? "Dalam perjalanan"
127:         : latestDelivery?.status === "delivered"
128:         ? "Selesai"
129:         : latestDelivery?.status === "pending"
130:         ? "Diproses"
131:         : "—";
132: 
133:     return [
134:       {
135:         title: "Status batch terakhir",
136:         subtitle: "Monitoring operasional",
137:         icon: Activity,
138:         content: latestDelivery ? statusLabel : "Belum ada data",
139:         detail: latestDelivery
140:           ? `Batch #${latestDelivery.id} • ${latestDelivery.tanggal} • ${latestDelivery.porsi_dikirim} box`
141:           : "Manifest belum tersedia.",
142:       },
143:       {
144:         title: "Jadwal pengiriman",
145:         subtitle: "Window penerimaan",
146:         icon: ShieldCheck,
147:         content: `Target: ${latestDelivery?.jam_target ?? "07:00"} WIB`,
148:         detail:
149:           latestDelivery?.jam_tiba && latestDelivery.jam_tiba !== "--"
150:             ? `Tiba: ${latestDelivery.jam_tiba} WIB`
151:             : "Armada belum tiba.",
152:       },
153:       {
154:         title: "Mitra vendor pelaksana",
155:         subtitle: "PIC vendor",
156:         icon: Phone,
157:         content: primaryRelation?.vendor.nama ?? "—",
158:         detail: primaryRelation?.vendor.no_telp
159:           ? `${primaryRelation.vendor.kontak_pic} • ${primaryRelation.vendor.no_telp}`
160:           : "Kontak belum tersedia.",
161:       },
162:       {
163:         title: "Dapur SPPG penanggung jawab",
164:         subtitle: "Verifikasi & pengolahan",
165:         icon: MapPin,
166:         content: availableSPPG?.nama ?? "Belum terhubung",
167:         detail: availableSPPG
168:           ? `${availableSPPG.kecamatan}, ${availableSPPG.kota} • Kapasitas ${availableSPPG.kapasitas_porsi}/hari`
169:           : "SPPG belum terhubung.",
170:       },
171:     ] as const;
172:   }, [availableSPPG, latestDelivery, primaryRelation]);
173: 
174:   const stats = useMemo(() => {
175:     if (viewMode === "school" && loggedInSchool) {
176:       return [
177:         { label: "Total siswa", value: loggedInSchool.total_siswa, unit: "jiwa", icon: Users },
178:         { label: "Penerima makan", value: loggedInSchool.total_siswa, unit: "porsi", icon: Activity },
179:         { label: "Mitra terafiliasi", value: availableVendors.length, unit: "vendor", icon: ShieldCheck },
180:         { label: "SPPG terhubung", value: availableSPPG ? 1 : 0, unit: "dapur", icon: MapPin },
181:       ] as const;
182:     }
183: 
184:     return [
185:       { label: "Sekolah aktif", value: sekolahList.length, unit: "unit", icon: SchoolIcon },
186:       { label: "Penerima makan", value: 2693, unit: "/hari", icon: Activity },
187:       { label: "Mitra terafiliasi", value: 5, unit: "vendor", icon: ShieldCheck },
188:       { label: "SPPG aktif", value: 4, unit: "dapur", icon: MapPin },
189:     ] as const;
190:   }, [availableSPPG, availableVendors.length, loggedInSchool, viewMode]);
191: 
192:   return (
193:     <>
194:       <DashboardShell
195:         badge={<Badge variant="outline" className="text-role-primary border-role-primary/30 bg-role-primary/5">Sekolah • Admin</Badge>}
196:         title="Dashboard Sekolah"
197:         description="Pantau distribusi dan koordinasi manifest dari vendor → SPPG → sekolah."
198:         actions={
199:           <div className="flex flex-wrap items-center gap-2">
200:             <div className="inline-flex items-center rounded-lg border border-border bg-muted p-1">
201:               <Button
202:                 size="sm"
203:                 variant={viewMode === "school" ? "default" : "ghost"}
204:                 onClick={() => setViewMode("school")}
205:                 className={viewMode === "school" ? "bg-role-primary hover:bg-role-primary-hover text-white shadow-sm" : ""}
206:               >
207:                 Konteks sekolah
208:               </Button>
209:               <Button
210:                 size="sm"
211:                 variant={viewMode === "aggregate" ? "default" : "ghost"}
212:                 onClick={() => setViewMode("aggregate")}
213:                 className={viewMode === "aggregate" ? "bg-role-primary hover:bg-role-primary-hover text-white shadow-sm" : ""}
214:               >
215:                 Agregat sistem
216:               </Button>
217:             </div>
218:           </div>
219:         }
220:       >
221:         <div className="flex flex-col md:flex-row gap-6 items-start mt-4">
222:           {/* Sticky Scrollspy Navigasi Kategori (Kecil Proporsi & 60-30-10 Light Theme) */}
223:           <aside className="w-full md:w-52 shrink-0 sticky top-24 z-30">
224:             <div className="bg-white/90 backdrop-blur-sm border border-violet-200/80 rounded-2xl p-2.5 shadow-sm space-y-2">
225:               <div className="px-3 pt-1 flex items-center justify-between">
226:                 <p className="text-[10px] font-extrabold uppercase tracking-wider text-violet-900/60">
227:                   Navigasi
228:                 </p>
229:                 <span className="size-1.5 rounded-full bg-violet-600 animate-ping" />
230:               </div>
231:               <nav className="flex flex-col space-y-1">
232:                 {CATEGORIES.map((cat) => (
233:                   <button
234:                     key={cat.id}
235:                     onClick={() => scrollToCategory(cat.id)}
236:                     className={cn(
237:                       "flex items-center justify-between px-3 py-2.5 text-xs font-semibold rounded-xl transition-all duration-200 text-left cursor-pointer",
238:                       activeCategory === cat.id
239:                         ? "bg-violet-600 text-white font-bold shadow-md shadow-violet-500/20 border border-violet-500"
240:                         : "text-slate-600 hover:bg-violet-50 hover:text-violet-700 border border-transparent"
241:                     )}
242:                   >
243:                     <span>{cat.label}</span>
244:                     {activeCategory === cat.id && (
245:                       <span className="size-1.5 rounded-full bg-white animate-pulse" />
246:                     )}
247:                   </button>
248:                 ))}
249:               </nav>
250:             </div>
251:           </aside>
252: 
253:           {/* Konten Utama (Render Semua Section untuk Scrollspy) */}
254:           <main className="flex-1 min-w-0 space-y-14 pb-16">
255:             
256:             {/* SECTION 1: OVERVIEW & DISTRIBUSI */}
257:             <section id="overview" className="space-y-6 scroll-mt-24">
258:               <div className="border-l-4 border-violet-600 pl-3.5 py-0.5">
259:                 <h2 className="text-xl font-bold tracking-tight text-slate-900">Overview &amp; Peta Distribusi</h2>
260:                 <p className="text-xs text-slate-500 mt-0.5">Ringkasan statistik harian serta pemetaan geografis sekolah.</p>
261:               </div>
262: 
263:               <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="Ringkasan sekolah">
264:                 {stats.map((stat) => (
265:                   <KpiCard
266:                     key={stat.label}
267:                     title={stat.label}
268:                     value={<CountUp to={stat.value} />}
269:                     unit={stat.unit}
270:                     icon={<stat.icon className="size-4" aria-hidden />}
271:                   />
272:                 ))}
273:               </div>
274: 
275:               <div className="grid gap-6 lg:grid-cols-12">
276:                 <Card className="lg:col-span-8 shadow-sm">
277:                   <CardHeader>
278:                     <CardTitle>Peta distribusi</CardTitle>
279:                     <CardDescription>Klik lokasi sekolah untuk melihat detail integrasi logistik.</CardDescription>
280:                   </CardHeader>
281:                   <CardContent>
282:                     <div className="h-[500px] overflow-hidden rounded-xl border border-border bg-muted/10">
283:                       <MapLibreMap
284:                         selectedSchool={selectedSchool}
285:                         onSchoolSelect={setSelectedSchool}
286:                         userSchoolId={loggedInSchool?.id}
287:                       />
288:                     </div>
289:                   </CardContent>
290:                 </Card>
291: 
292:                 <div className="lg:col-span-4 space-y-4"> 
293:                   {selectedSchool ? ( 
294:                     <SchoolDetailPanel 
295:                       school={selectedSchool} 
296:                       vendors={getVendorsBySekolah(selectedSchool.id)} 
297:                       onClose={() => setSelectedSchool(null)} 
298:                       readOnly={selectedSchool.id !== (loggedInSchool?.id ?? 0)} 
299:                     /> 
300:                   ) : ( 
301:                     <Card className="shadow-sm"> 
302:                       <CardHeader> 
303:                         <CardTitle>Panel Identitas Operasional</CardTitle> 
304:                         <CardDescription>Ringkasan status penerimaan dan mitra aktif.</CardDescription> 
305:                       </CardHeader> 
306:                       <CardContent className="space-y-3"> 
307:                         {identityPanels.map((panel) => ( 
308:                           <div key={panel.title} className="rounded-xl border border-border p-4 bg-muted/20">
309:                             <div className="flex items-start gap-3">
310:                               <div className="mt-0.5 rounded-lg bg-background p-2 text-role-primary shadow-sm">
311:                                 <panel.icon className="size-4" />
312:                               </div>
313:                               <div className="min-w-0">
314:                                 <p className="text-sm font-semibold">{panel.title}</p>
315:                                 <p className="text-xs text-muted-foreground">{panel.subtitle}</p>
316:                               </div>
317:                             </div>
318:                             <div className="mt-3 space-y-1">
319:                               <p className="text-sm font-medium text-foreground">{panel.content}</p>
320:                               <p className="text-xs text-muted-foreground">{panel.detail}</p>
321:                             </div>
322:                           </div>
323:                         ))}
324:                       </CardContent> 
325:                     </Card> 
326:                   )} 
327:                 </div> 
328:               </div>
329:             </section>
330: 
331:             {/* SECTION 2: VALIDASI LOGISTIK */}
332:             <section id="validasi" className="space-y-6 scroll-mt-24">
333:               <div className="border-l-4 border-violet-600 pl-3.5 py-0.5">
334:                 <h2 className="text-xl font-bold tracking-tight text-slate-900">Validasi Logistik &amp; Serah Terima</h2>
335:                 <p className="text-xs text-slate-500 mt-0.5">Pemindaian QR Code bukti fisik serah terima barang di lokasi (Phase 3).</p>
336:               </div>
337: 
338:               <Card className="overflow-hidden border border-border/80 shadow-sm bg-gradient-to-br from-background to-muted/20">
339:                 <div className="h-1.5 w-full bg-emerald-500" />
340:                 <CardHeader className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-6">
341:                   <div>
342:                     <CardTitle className="text-xl">Validasi Penerimaan Logistik</CardTitle>
343:                     <CardDescription className="text-sm mt-1">
344:                       Generate QR Code agar mitra pengirim (vendor / armada) dapat melakukan pemindaian serah terima di lokasi.
345:                     </CardDescription>
346:                   </div>
347:                   <Button 
348:                     className="rounded-full shadow-md bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5" 
349:                     onClick={() => setScanOpen(true)}
350:                   >
351:                     <QrCode className="w-4 h-4 mr-2" />
352:                     Generate QR Terima
353:                   </Button>
354:                 </CardHeader>
355:                 <CardContent>
356:                   <div className="flex flex-col sm:flex-row gap-6 sm:items-center justify-between">
357:                     <div className="rounded-2xl border border-border bg-background p-5 flex-1 shadow-sm">
358:                       <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Scan Terakhir Oleh Mitra</p>
359:                       <div className="flex items-center gap-3">
360:                         <div className={cn("size-2.5 rounded-full", lastScan ? "bg-emerald-500 animate-pulse" : "bg-muted-foreground/30")} />
361:                         <p className="font-mono text-sm text-foreground break-all font-semibold">
362:                           {lastScan ?? "Belum ada pemindaian hari ini"}
363:                         </p>
364:                       </div>
365:                     </div>
366:                     <div className="flex-1">
367:                       <p className="text-xs text-muted-foreground leading-relaxed">
368:                         Setelah QR Code berhasil dipindai oleh pihak pengirim menggunakan aplikasi mereka, status serah terima pesanan (manifest) akan otomatis terverifikasi di dalam sistem audit B.O.G.A.
369:                       </p>
370:                     </div>
371:                   </div>
372:                 </CardContent>
373:               </Card>
374:             </section>
375: 
376:             {/* SECTION 3: MITRA OPERASIONAL */}
377:             <section id="mitra" className="space-y-6 scroll-mt-24">
378:               <div className="border-l-4 border-violet-600 pl-3.5 py-0.5">
379:                 <h2 className="text-xl font-bold tracking-tight text-slate-900">Mitra Operasional &amp; Reputasi</h2>
380:                 <p className="text-xs text-slate-500 mt-0.5">Audit performa individu vendor &amp; dapur SPPG serta leaderboard peringkat.</p>
381:               </div>
382: 
383:               <Card className="shadow-sm">
384:                 <CardHeader className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
385:                   <div>
386:                     <CardTitle>Audit &amp; Ranking Mitra</CardTitle>
387:                     <CardDescription>Pantau performa individu atau peringkat mitra teratas (Vendor &amp; SPPG).</CardDescription>
388:                   </div>
389:                   <div className="flex bg-muted/50 p-1 rounded-lg border border-border">
390:                     <Button 
391:                       variant={activeMitraTab === "performa" ? "default" : "ghost"} 
392:                       size="sm"
393:                       className={cn("rounded-md text-xs font-semibold", activeMitraTab === "performa" && "bg-violet-600 text-white shadow-sm")}
394:                       onClick={() => setActiveMitraTab("performa")}
395:                     >
396:                       Audit Performa
397:                     </Button>
398:                     <Button 
399:                       variant={activeMitraTab === "ranking" ? "default" : "ghost"} 
400:                       size="sm"
401:                       className={cn("rounded-md text-xs font-semibold", activeMitraTab === "ranking" && "bg-violet-600 text-white shadow-sm")}
402:                       onClick={() => setActiveMitraTab("ranking")}
403:                     >
404:                       Leaderboard Ranking
405:                     </Button>
406:                   </div>
407:                 </CardHeader>
408:                 <CardContent>
409:                   {activeMitraTab === "performa" ? (
410:                     <div className="max-w-4xl mx-auto pt-2">
411:                       <div className="flex flex-wrap items-center gap-2 pb-6 border-b border-border/50 mb-6">
412:                         <Label htmlFor="entityId" className="text-sm font-medium">
413:                           Target Entity ID
414:                         </Label>
415:                         <Input
416:                           id="entityId"
417:                           type="number"
418:                           value={selectedEntityId}
419:                           onChange={(e) => setSelectedEntityId(Number(e.target.value))}
420:                           className="h-9 w-28 text-center"
421:                         />
422:                         <Badge variant="secondary" className="bg-violet-100 text-violet-700 border-none font-bold">type: sppg</Badge>
423:                       </div>
424:                       <VendorPerformanceDashboard type="sppg" entityId={selectedEntityId} />
425:                     </div>
426:                   ) : (
427:                     <div className="space-y-8 bg-slate-50/50 p-4 sm:p-6 rounded-2xl border border-border/40">
428:                       <VendorRanking type="vendor" />
429:                       <Separator />
430:                       <VendorRanking type="sppg" />
431:                     </div>
432:                   )}
433:                 </CardContent>
434:               </Card>
435:             </section>
436: 
437:             {/* SECTION 4: BANTUAN & TIKET */}
438:             <section id="bantuan" className="space-y-6 scroll-mt-24">
439:               <div className="border-l-4 border-violet-600 pl-3.5 py-0.5">
440:                 <h2 className="text-xl font-bold tracking-tight text-slate-900">Bantuan &amp; Tiket Kendala</h2>
