444:               <div className="grid gap-6 lg:grid-cols-2">
445:                 <Card className="shadow-sm">
446:                   <CardHeader>
447:                     <CardTitle>Kontak Bantuan Operasional</CardTitle>
448:                     <CardDescription>Kanal respon cepat untuk penanganan isu teknis dan pengiriman.</CardDescription>
449:                   </CardHeader>
450:                   <CardContent className="space-y-4 text-sm">
