462:                         <MessageSquare className="size-4" />
463:                       </div>
464:                       <div>
465:                         <p className="text-xs font-medium text-muted-foreground">WhatsApp Support</p>
466:                         <p className="font-bold text-base mt-0.5">+62 811 2345 6789</p>
467:                       </div>
468:                     </div>
469:                     <div className="flex items-start gap-3 rounded-xl border border-border bg-muted/20 p-4 hover:border-role-primary/30 transition-colors">
470:                       <div className="mt-0.5 rounded-lg bg-background p-2 text-role-primary shadow-sm">
471:                         <Mail className="size-4" />
472:                       </div>
473:                       <div>
474:                         <p className="text-xs font-medium text-muted-foreground">Email Resmi</p>
